"""CrewAI integration — StrataCrewMemory for persistent crew memory.

Install: pip install strata-memory[crewai]
"""

from __future__ import annotations

from typing import Any

from strata.client import StrataClient


class StrataCrewMemory:
    """Persistent memory for CrewAI crews backed by Strata.

    Provides ``store()`` and ``search()`` methods compatible with CrewAI's
    memory interface. Memories persist across crew runs.

    Usage::

        from strata import StrataClient
        from strata.integrations.crewai import StrataCrewMemory

        s = StrataClient()
        memory = StrataCrewMemory(client=s, project="research-crew")

        memory.store("Found that React 19 uses compiler optimizations")
        results = memory.search("React optimizations")
    """

    def __init__(
        self,
        client: StrataClient,
        *,
        project: str | None = None,
        user: str | None = None,
    ) -> None:
        self._client = client
        self._project = project
        self._user = user

    def store(
        self,
        text: str,
        *,
        type: str = "learning",
        tags: list[str] | None = None,
    ) -> dict[str, Any]:
        """Store a memory from a crew agent. Returns dict with memory id."""
        mem = self._client.add(
            text,
            type=type,
            tags=tags,
            project=self._project,
            user=self._user,
        )
        return {"id": mem.id, "type": mem.type, "summary": mem.summary}

    def search(
        self,
        query: str,
        *,
        limit: int = 10,
    ) -> list[dict[str, Any]]:
        """Search crew memories. Returns list of result dicts."""
        results = self._client.search(
            query,
            limit=limit,
            project=self._project,
            user=self._user,
        )
        return [
            {"text": r.text, "score": r.score, "project": r.project or ""}
            for r in results
        ]

    def find_solutions(self, query: str, *, limit: int = 5) -> list[dict[str, Any]]:
        """Find solutions from past crew runs."""
        results = self._client.find_solutions(
            query, limit=limit, project=self._project
        )
        return [{"text": r.text, "score": r.score} for r in results]
